# if/else 判断奇偶
n = int(input())
if n % 2 == 0:
    print("偶数")
else:
    print("奇数")

# 输出两个数中较大的
a, b = map(int, input().split())
if a > b:
    print(a)
else:
    print(b)

# 分数段分级:0-59 为 E,60 起依次 D/C/B/A
score = int(input())
if score >= 90:
    print("A")
elif score >= 80:
    print("B")
elif score >= 70:
    print("C")
elif score >= 60:
    print("D")
else:
    print("E")

# 闰年:能被4整除且(不能被100整除或能被400整除)
year = int(input())
if (year % 4 == 0 and year % 100 != 0) or year % 400 == 0:
    print("yes")
else:
    print("no")

# 判断正数/负数/零
n = int(input())
if n > 0:
    print("正数")
elif n < 0:
    print("负数")
else:
    print("零")

# 三个数取最大:两两比较
a, b, c = map(int, input().split())
if a >= b and a >= c:
    print(a)
elif b >= a and b >= c:
    print(b)
else:
    print(c)
